import { useState } from "react";

export type DockItem = {
  id: string;
  label: string;
  glyph: string;
  running?: boolean;
};

export function AppDock({
  items,
  activeId,
  onSelect,
}: {
  items: DockItem[];
  activeId: string;
  onSelect: (id: string) => void;
}) {
  const [hovered, setHovered] = useState<string | null>(null);

  return (
    <nav className="dock-root" aria-label="Application dock">
      {items.map((item, index) => {
        const distance =
          hovered === null
            ? 0
            : Math.abs(items.findIndex((i) => i.id === hovered) - index);
        const scale = hovered === null ? 1 : Math.max(1, 1.4 - distance * 0.12);

        return (
          <button
            key={item.id}
            type="button"
            title={item.label}
            aria-label={item.label}
            aria-current={item.id === activeId}
            onClick={() => onSelect(item.id)}
            onMouseEnter={() => setHovered(item.id)}
            onMouseLeave={() => setHovered(null)}
            onFocus={() => setHovered(item.id)}
            onBlur={() => setHovered(null)}
            className={item.id === activeId ? "dock-item is-active" : "dock-item"}
            style={{ transform: `scale(${scale}) translateY(${(scale - 1) * -8}px)` }}
          >
            <span aria-hidden="true">{item.glyph}</span>
            {item.running ? <i className="dock-dot" /> : null}
          </button>
        );
      })}
    </nav>
  );
}

