.dock-root {
  display: flex;
  align-items: flex-end;
  gap: 8px;
  padding: 8px 12px;
  border-radius: 18px;
  background: var(--surface-glass, rgba(255, 255, 255, 0.14));
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
  border: 1px solid var(--line-subtle, rgba(255, 255, 255, 0.22));
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.28);
}
.dock-item {
  position: relative;
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  font-size: 18px;
  border: none;
  border-radius: 12px;
  background: var(--surface-raised, rgba(255, 255, 255, 0.1));
  color: var(--text-strong, #f8fafc);
  cursor: pointer;
  transition: transform 0.16s cubic-bezier(0.16, 1, 0.3, 1);
  transform-origin: bottom center;
}
.dock-item.is-active {
  box-shadow: inset 0 0 0 2px var(--accent, #6366f1);
}
.dock-item:focus-visible {
  outline: 2px solid var(--accent, #6366f1);
  outline-offset: 2px;
}
.dock-dot {
  position: absolute;
  bottom: -6px;
  left: 50%;
  transform: translateX(-50%);
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--text-strong, #f8fafc);
}
@media (prefers-reduced-motion: reduce) {
  .dock-item {
    transition: none;
  }
}
